mapper.update:
update sys_user
username = #{username}, name = #{name}, password = #{password}, email = #{email}, mobile = #{mobile}, status = #{status}, gmt_modified = now()
where user_id = #{userId}

update sys_role
role_name = #{roleName}, role_sign = #{roleSign}, remark = #{remark}, gmt_modified = now()
where role_id = #{roleId}

update sys_menu
parent_id = #{parentId}, name = #{name}, url = #{url}, perms = #{perms}, type = #{type}, icon = #{icon}, order_num = #{orderNum}, gmt_modified = now()
where menu_id = #{menuId}
